do $$ declare v_count integer; begin select count(*) into v_count from (select p.id,p.credits,coalesce(sum(case when t.status='completed' and t.type='credit' then t.amount when t.status='completed' and t.type='debit' then -t.amount else 0 end),0) ledger from public.profiles p left join public.transactions t on t.user_id=p.id group by p.id,p.credits having p.credits<>coalesce(sum(case when t.status='completed' and t.type='credit' then t.amount when t.status='completed' and t.type='debit' then -t.amount else 0 end),0)) q; if v_count<>0 then raise exception 'wallet/ledger mismatch count=%',v_count; end if; raise notice 'wallet reconciliation passed'; end $$;
